        capacity = newCap;
    }
    // Copy bytes or fill with zeros
    if(byteArrayValue != null){
        System.arraycopy(byteArrayValue, byteOffset, buffer, size, byteLength);
    } else {
        for(int i = 0; i < byteLength; i++){
            buffer[size + i] = 0;
        }
    }
    size = newSize;
    return this;
}

