private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int count = 0;
    int i = 0;
    try {
        if (descriptor.charAt(0) == '(') {
            i = 1;
            while (i < descriptor.length() && descriptor.charAt(i) != ')') {
                char c = descriptor.charAt(i);
                if (c == '[') {
                    // Skip all '[' characters
                    while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                        i++;
                    }
                    // After array brackets, there is a type
                    if (i < descriptor.length() && descriptor.charAt(i) == 'L') {
                        i++; // skip 'L'
                        while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                            i++;
                        }
                        i++; // skip ';'
                    } else {
                        // Primitive type after array brackets
                        i++;
                    }
                } else if (c == 'L') {
                    i++; // skip 'L'
                    while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++; // skip ';'
                } else {
                    // Primitive type
                    i++;
                }
                count++;
            }
        } else {
            // Single type descriptor
            count = 1;
        }
    } catch (IndexOutOfBoundsException e) {
        // Malformed descriptor; do nothing
        return;
    }
    // Pop the counted number of types from the output frame stack
    for (int j = 0; j < count; j++) {
        if (!outputFrameStack.isEmpty()) {
            outputFrameStack.pop();
        } else {
            // Stack underflow; stop popping
            break;
        }
    }
}

