    if (value == null) {
        return null;
    }
    // Only handle conversion to Character or char
    if (Character.class.equals(type) || type == char.class) {
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof String) {
            String s = (String) value;
            if (s.length() == 1) {
                return s.charAt(0);
            } else {
                throw new IllegalArgumentException("Cannot convert String of length " + s.length() + " to Character");
            }
        }
        if (value instanceof Number) {
            int intVal = ((Number) value).intValue();
            if (intVal >= Character.MIN_VALUE && intVal <= Character.MAX_VALUE) {
                return (char) intVal;
            } else {
                throw new IllegalArgumentException("Numeric value out of char range: " + intVal);
            }
        }
        // Unsupported source type for Character conversion
        throw new IllegalArgumentException("Unsupported source type for Character conversion: " + value.getClass().getName());
    }
    // If the target type is not Character, throw an exception
    throw new IllegalArgumentException("Target type is not Character: " + type.getName());
}

