@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null");
    }
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }
    // Add vertices
    for (V v : resultMap.values()) {
        if (!target.containsVertex(v)) {
            target.addVertex(v);
        }
    }
    // Partition vertices into two sets based on key prefix
    Set<V> left = new HashSet<>();
    Set<V> right = new HashSet<>();
    for (Map.Entry<String,V> entry : resultMap.entrySet()) {
        String key = entry.getKey();
        V v = entry.getValue();
        if (key != null && key.toLowerCase().startsWith("left")) {
            left.add(v);
        } else {
            right.add(v);
        }
    }
    // If left or right is empty, fallback to split by index
    if (left.isEmpty() || right.isEmpty()) {
        List<V> vertices = new ArrayList<>(resultMap.values());
        int mid = vertices.size() / 2;
        left.clear();
        right.clear();
        for (int i = 0; i < vertices.size(); i++) {
            if (i < mid) {
                left.add(vertices.get(i));
            } else {
                right.add(vertices.get(i));
            }
        }
    }
    // Add edges between all pairs of left and right
    for (V u : left) {
        for (V v : right) {
            if (!target.containsEdge(u, v)) {
                try {
                    target.addEdge(u, v);
                } catch (Exception e) {
                    // ignore edge addition failures
                }
            }
        }
    }
}

