    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node cannot be null");
    }

    Node current = start;
    OuterFaceCirculator circulator = new OuterFaceCirculator(current);

    while (true) {
        if (predicate.test(current)) {
            return circulator;
        }
        if (current.equals(stop)) {
            return circulator;
        }

        // Move to the next node in the specified direction.
        // If the underlying graph structure does not provide a direct method,
        // this will need to be adapted to the actual API.
        Node next = current.getNext(dir);
        if (next == null) {
            // If we cannot advance further, return a circulator to the stop node
