protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null) {
        throw new IllegalArgumentException("Tour set cannot be null");
    }
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }
    if (tour.isEmpty()) {
        return new DefaultGraphPath<>(graph, new ArrayList<>(), new ArrayList<>(), 0.0);
    }
    // Build adjacency map (undirected)
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge not present in graph: " + e);
        }
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
    }
    // Start traversal from an arbitrary vertex
    V start = adjacency.keySet().iterator().next();
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();
    V current = start;
    E previousEdge = null;
    while (true) {
        vertexList.add(current);
        List<E> edges = adjacency.get(current);
        if (edges == null) {
            break;
        }
        E nextEdge = null;
        for (E e : edges) {
            if (!visitedEdges.contains(e) && e != previousEdge) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            break;
        }
        edgeList.add(nextEdge);
        visitedEdges.add(nextEdge);
        previousEdge = nextEdge;
        V src = graph.getEdgeSource(nextEdge);
        V tgt = graph.getEdgeTarget(nextEdge);
        current = src.equals(current) ? tgt : src;
        if (current.equals(start) && visitedEdges.size() == tour.size()) {
            break;
        }
    }
    if (visitedEdges.size() != tour.size()) {
        throw new IllegalArgumentException("Provided edge set does not form a single tour");
    }
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }
    return new DefaultGraphPath<>(graph, vertexList, edgeList, weight);
}

