private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> globalList = new ArrayList<>();
    if (graph == null) {
        return globalList;
    }
    try {
        for (E edge : graph.getEdges()) {
            Object u = graph.getSource(edge);
            Object v = graph.getTarget(edge);
            if (u == null || v == null) {
                continue;
            }
            Set<Object> neighborsU = graph.getNeighbors(u);
            Set<Object> neighborsV = graph.getNeighbors(v);
            if (neighborsU == null) neighborsU = new HashSet<>();
            if (neighborsV == null) neighborsV = new HashSet<>();
            Set<Object> neighborhood = new HashSet<>(neighborsU);
            neighborhood.addAll(neighborsV);
            List<Pair<Integer,Integer>> separators = new ArrayList<>();
            List<Object> list = new ArrayList<>(neighborhood);
            for (int i = 0; i < list.size(); i++) {
                for (int j = i + 1; j < list.size(); j++) {
                    int idA = list.get(i).hashCode();
                    int idB = list.get(j).hashCode();
                    separators.add(new Pair<>(idA, idB));
                }
            }
            globalList.add(new Pair<>(separators, edge));
        }
    } catch (Exception ex) {
        // Exception handling: log or ignore
    }
    return globalList;
}

