private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    int[] temp = new int[n];
    long running = 0;
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            val = 0;
        }
        running += val;
        temp[i] = (int) running;
    }
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffix.add(temp[i]);
    }
    long total = 0;
    for (Integer val : bounds) {
        if (val != null) {
            total += val;
        }
    }
    return new Pair<>(suffix, total);
}

