private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null) {
        return result;
    }
    for (K key : keys) {
        if (key == null) {
            result.add(null);
            continue;
        }
        if (!(key instanceof Comparable)) {
            throw new IllegalArgumentException("Key must implement Comparable");
        }
        Comparable<? super K> compKey = (Comparable<? super K>) key;
        K best = null;
        for (K other : keys) {
            if (other == null) {
                continue;
            }
            if (compKey.compareTo(other) >= 0) {
                if (best == null || ((Comparable<? super K>) other).compareTo(best) > 0) {
                    best = other;
                }
            }
        }
        if (best != null) {
            if (best instanceof Integer) {
                result.add((Integer) best);
            } else {
                try {
                    result.add(Integer.parseInt(best.toString()));
                } catch (NumberFormatException e) {
                    result.add(null);
                }
            }
        } else {
            result.add(null);
        }
    }
    return result;
}

