public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        if (i + 1 >= str.length()) {
            throw new IllegalArgumentException("Trailing backslash at end of string");
        }
        char next = str.charAt(i + 1);
        switch (next) {
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case '\"':
                sb.append('\"');
                i++;
                break;
            case '\'':
                sb.append('\'');
                i++;
                break;
            case '\\':
                sb.append('\\');
                i++;
                break;
            case 'u':
                if (i + 5 >= str.length()) {
                    throw new IllegalArgumentException("Incomplete unicode escape sequence");
                }
                String hex = str.substring(i + 2, i + 6);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid unicode escape: \\u" + hex);
                }
                i += 5;
                break;
            default:
                // For any other escape, treat the next character literally
                sb.append(next);
                i++;
                break;
        }
    }
    return sb.toString();
}

