public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    try {
        java.nio.file.Path base = java.nio.file.Paths.get(path);
        java.nio.file.Path resolved = base.resolve(relativePath).normalize();
        String result = resolved.toString();
        // Convert backslashes to forward slashes for consistency
        if (System.getProperty("file.separator").equals("\\")) {
            result = result.replace("\\", "/");
        }
        return result;
    } catch (Exception e) {
        throw new RuntimeException("Failed to apply relative path", e);
    }
}

