public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("buf cannot be null");
    }
    if (nameStart < 0 || nameStart > buf.length()) {
        throw new IllegalArgumentException("nameStart out of bounds");
    }
    try {
        String fullName = buf.toString();
        if (nameStart >= fullName.length()) {
            return; // nothing to abbreviate
        }
        String sub = fullName.substring(nameStart);
        if (sub.isEmpty()) {
            return;
        }
        String[] parts = sub.split("[._]");
        StringBuilder abbr = new StringBuilder();
        for (int i = 0; i < parts.length; i++) {
            if (!parts[i].isEmpty()) {
                abbr.append(parts[i].charAt(0));
                if (i < parts.length - 1) {
                    abbr.append('.');
                }
            }
        }
        // Replace the original part with its abbreviation
        buf.delete(nameStart, buf.length());
        buf.append(abbr);
    } catch (Exception e) {
        // Log or rethrow as unchecked if desired
        throw new RuntimeException("Failed to abbreviate name", e);
    }
}

