protected java.util.List<TimeRange> buildTimeRanges(long start, long end) {
    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();
    try {
        if (start > end) {
            throw new IllegalArgumentException("Start time must be less than or equal to end time");
        }
        if (FETCH_DATA_DURATION <= 0) {
            throw new IllegalStateException("FETCH_DATA_DURATION must be a positive value");
        }
        long current = start;
        while (current < end) {
            long next = Math.min(current + FETCH_DATA_DURATION, end);
            ranges.add(new TimeRange(current, next));
            current = next;
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to build time ranges", e);
    }
    return ranges;
}

