public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 3) {
        return 3;
    }
    int candidate = desiredCapacity;
    if ((candidate & 1) == 0) {
        candidate++; // make it odd
    }
    int max = desiredCapacity >= 1000 ? (int) (desiredCapacity * 1.11) + 1 : Integer.MAX_VALUE;
    while (candidate <= max) {
        boolean prime = true;
        if (candidate <= 3) {
            prime = true;
        } else if (candidate % 2 == 0 || candidate % 3 == 0) {
            prime = false;
        } else {
            for (int i = 5; i * i <= candidate; i += 6) {
                if (candidate % i == 0 || candidate % (i + 2) == 0) {
                    prime = false;
                    break;
                }
            }
        }
        if (prime) {
            return candidate;
        }
        candidate += 2; // skip even numbers
    }
    // Fallback: return the candidate found (may exceed the 11% bound)
    return candidate;
}

