        out.write(new byte[]{0, 0, 0, 0});
        return 0;
    }
    // Compute serialized size
    int size = schema.getSerializedSize(message, buffer);
    // Write length prefix as 4-byte big-endian
    byte[] lenBytes = new byte[4];
    lenBytes[0] = (byte) ((size >> 24) & 0xFF);
    lenBytes[1] = (byte) ((size >> 16) & 0xFF);
    lenBytes[2] = (byte) ((size >> 8) & 0xFF);
    lenBytes[3] = (byte) (size & 0xFF);
    out.write(lenBytes);
    // Serialize the message
    schema.writeTo(out, message, buffer);
    return size;
}

