public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if(str == null){
        throw new NullPointerException("str");
    }
    if(index < 0 || len < 0){
        throw new IndexOutOfBoundsException("index or len negative");
    }
    int end = index + len;
    if(end > str.length()){
        throw new IndexOutOfBoundsException("index+len exceeds string length");
    }
    int size = 0;
    int i = index;
    while(i < end){
        int cp = str.codePointAt(i);
        i += Character.charCount(cp);
        if(cp <= 0x7F){
            size += 1;
        }else if(cp <= 0x7FF){
            size += 2;
        }else if(cp <= 0xFFFF){
            size += 3;
        }else{
            size += 4;
        }
    }
    return size;
}

