int function ( final DataOutput out , LinkedBuffer node ) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput cannot be null");
    }
    if (node == null) {
        return 0;
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        byte[] buffer = current.getBuffer();
        int length = current.getSize();
        if (buffer != null && length > 0) {
            out.write(buffer, 0, length);
            totalSize += length;
        }
        current = current.getNext();
    }
    return totalSize;
}

